import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B="http://localhost:8080";tok=None;notes=[]
def gettok():
    global tok
    while True:
        try: tok=json.load(urllib.request.urlopen(urllib.request.Request(B+"/token",method="POST",data=b"")))["token"];return
        except urllib.error.HTTPError as e:
            time.sleep(float(e.headers.get("Retry-After") or 1))
def get(p):
    global tok
    if not tok: gettok()
    for i in range(200):
        try: return json.load(urllib.request.urlopen(urllib.request.Request(B+p,headers={"Authorization":"Bearer "+tok})))
        except urllib.error.HTTPError as e:
            if e.code==401: gettok()
            elif e.code==429: time.sleep(float(e.headers.get("Retry-After") or 1))
            elif e.code==404 and "/customers/" in p: return None
            else: notes.append((p,e.code)); time.sleep(0.5)
        except Exception as e: notes.append((p,str(e))); time.sleep(0.5)
    raise SystemExit("fail "+p)
seen={};dups=0;page=1;statuses=set()
while True:
    d=get(f"/orders?page={page}")
    for o in d["items"]:
        if o["id"] in seen:
            dups+=1
            if seen[o["id"]]!=o: notes.append(("dupdiff",o,seen[o["id"]]))
        else: seen[o["id"]]=o
        statuses.add(o["status"])
    if not d["next"]: break
    page+=1
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};tot=0;n=0;reg={k:0 for k in["north","south","east","west"]};odd=[]
for o in seen.values():
    if o["status"]!="shipped": continue
    s=o["placed_at"].replace("Z","+00:00");t=datetime.fromisoformat(s)
    if t.tzinfo is None: odd.append(("naive",o["placed_at"]));t=t.replace(tzinfo=timezone.utc)
    t=t.astimezone(timezone.utc)
    if not(lo<=t<hi): continue
    c=o["customer_id"]
    if c not in cust: cust[c]=get(f"/customers/{c}")
    cu=cust[c]
    if cu is None: odd.append(("nocust",o));continue
    a=o["amount_cents"];x=a*(100-cu["discount_pct"]);v=(x+50)//100
    if not isinstance(a,int) or a<0: odd.append(("amt",o))
    tot+=v;n+=1;reg[cu["region"]]+=v
json.dump({"total_cents":tot,"order_count":n,"duplicates_skipped":dups,"by_region":reg},open("/workspace/result.json","w"),indent=2)
print(tot,n,dups,reg,page,len(seen),statuses,odd[:10],len(odd),notes[:10],len(notes))
print(set(type(c["discount_pct"]) for c in cust.values() if c), [c for c in cust.values() if c and c["region"] not in reg])
EOF
